"""Kitchen Sink page: SpinBox, DTPicker, MonthView, Dial, LCDNumber, FontComboBox and
HotKey: numbers, dates and times, a knob, a seven-segment display, fonts and shortcuts."""

import datetime

from vp6 import *


class pgInputs(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Calendars, numbers and keys'
        self.Width = 640
        self.Height = 440
        self.lblQty = Label(self, Caption='Quantity:', Left=16, Top=20, Width=70, Height=22)
        self.spnQty = SpinBox(self, Left=90, Top=16, Width=110, Height=25, Max=1000, Value=10,
                              Increment=5, Suffix=' pcs', TabIndex=1,
                              ToolTipText='A SpinBox: whole numbers, in steps of 5')
        self.lblPrice = Label(self, Caption='Price:', Left=216, Top=20, Width=50, Height=22,
                              TabIndex=2)
        self.spnPrice = SpinBox(self, Left=266, Top=16, Width=120, Height=25, DecimalPlaces=2,
                                Max=999.99, Value=4.5, Increment=0.25, Prefix='EUR ', TabIndex=3,
                                ToolTipText='DecimalPlaces 2: its Value is a float')
        self.lcdTotal = LCDNumber(self, Left=404, Top=8, Width=220, Height=44, Digits=8,
                                  SegmentStyle=2,
                                  ToolTipText='An LCDNumber: the total; Overflow fires when it is too long')
        self.lblTotal = Label(self, Caption='', Left=16, Top=56, Width=600, Height=22, TabIndex=4)
        self.lblWhen = Label(self, Caption='When:', Left=16, Top=96, Width=70, Height=22,
                             TabIndex=5)
        self.dtpWhen = DTPicker(self, Left=90, Top=92, Width=250, Height=25, Format=3,
                                CustomFormat='ddd d MMM yyyy, HH:mm', TabIndex=6,
                                ToolTipText='A DTPicker with a CustomFormat: its arrow drops a calendar down')
        self.dtpDay = DTPicker(self, Left=350, Top=92, Width=130, Height=25, MinDate='2000-01-01',
                               UpDown=True, TabIndex=7,
                               ToolTipText='Short Date, UpDown arrows, no day before 2000')
        self.mvwDays = MonthView(self, Left=16, Top=130, Width=281, Height=233,
                                 ShowWeekNumbers=True, TabIndex=8,
                                 ToolTipText='A MonthView: today is in bold; click a day')
        self.lblDates = Label(self, Caption='', Left=16, Top=372, Width=281, Height=44,
                              WordWrap=True, TabIndex=9)
        self.dialSpeed = Dial(self, Left=316, Top=130, Width=90, Height=90, Max=255,
                              LargeChange=16, TabIndex=10,
                              ToolTipText='A Dial: drag it round, or use the arrow keys')
        self.lcdSpeed = LCDNumber(self, Left=420, Top=148, Width=110, Height=50, Digits=4, Mode=1,
                                  ToolTipText='Mode Hex: the Dial in hexadecimal')
        self.lblSpeed = Label(self, Caption='Turn the dial', Left=316, Top=228, Width=308,
                              Height=22, TabIndex=11)
        self.fcbFont = FontComboBox(self, Left=316, Top=266, Width=200, Height=25, TabIndex=12,
                                    ToolTipText='A FontComboBox: every font, drawn in itself')
        self.lblSample = Label(self, Caption='The quick brown fox', Left=316, Top=296, Width=308,
                               Height=30, TabIndex=13)
        self.hkyShortcut = HotKey(self, Left=316, Top=344, Width=180, Height=25,
                                  Keys='Ctrl+Shift+K', ClearButton=True, TabIndex=14,
                                  ToolTipText='A HotKey: click it and press a shortcut')
        self.lblKeys = Label(self, Caption='', Left=316, Top=376, Width=308, Height=40,
                             WordWrap=True, TabIndex=15)
    # endregion

    def Form_Load(self):
        self.mvwDays.DayBold[datetime.date.today()] = True
        self.dtpDay.Value = self.mvwDays.Value
        self.show_total()
        self.hkyShortcut_Change()

    # --- SpinBox and LCDNumber -----------------------------------------------------------
    def show_total(self):
        total = self.spnQty.Value * self.spnPrice.Value
        self.lblTotal.Caption = (f"{self.spnQty.Text} at {self.spnPrice.Text} = {total:.2f} "
                                 "(SpinBox Change)")
        self.lcdTotal.Value = round(total, 2)  # (too long: Overflow says so)

    def spnQty_Change(self):
        self.show_total()

    def spnPrice_Change(self):
        self.show_total()

    def lcdTotal_Overflow(self):
        self.lblTotal.Caption = "Overflow: the total doesn't fit in the display"

    # --- DTPicker and MonthView ----------------------------------------------------------
    def dtpWhen_Change(self):
        when = self.dtpWhen.Value  # a datetime
        self.lblDates.Caption = f"DTPicker: {when:%A %d %B %Y, %H:%M} (Hour {self.dtpWhen.Hour})"

    def dtpWhen_CloseUp(self):
        self.lblDates.Caption = f"CloseUp: the calendar closed on {self.dtpWhen.Text}"

    def dtpDay_Change(self):
        self.mvwDays.Value = self.dtpDay.Value  # (the calendar follows)

    def mvwDays_DateClick(self, DateClicked):
        self.dtpDay.Value = DateClicked
        self.lblDates.Caption = f"DateClick: {DateClicked:%A %d %B %Y}"

    def mvwDays_DateDblClick(self, DateDblClicked):
        bold = not self.mvwDays.DayBold(DateDblClicked)
        self.mvwDays.DayBold[DateDblClicked] = bold
        self.lblDates.Caption = f"DateDblClick: {DateDblClicked} is {'' if bold else 'not '}bold"

    # --- Dial ------------------------------------------------------------------------------
    def dialSpeed_Scroll(self):
        self.lcdSpeed.Value = self.dialSpeed.Value
        self.lblSpeed.Caption = f"Scroll: {self.dialSpeed.Value} (0x{self.dialSpeed.Value:X})"

    def dialSpeed_Change(self):
        self.lcdSpeed.Value = self.dialSpeed.Value
        self.lblSpeed.Caption = f"Change: the dial is at {self.dialSpeed.Value}"

    # --- FontComboBox and HotKey -----------------------------------------------------------
    def fcbFont_Click(self):
        self.lblSample.FontName = self.fcbFont.FontName
        self.lblSample.Caption = f"The quick brown fox ({self.fcbFont.FontName})"

    def hkyShortcut_Change(self):
        keys = self.hkyShortcut.Keys
        self.lblKeys.Caption = (f"HotKey: {keys or '(none)'} - KeyCode {self.hkyShortcut.KeyCode}, "
                                f"Shift {self.hkyShortcut.Shift}")


if __name__ == "__main__":
    run(pgInputs)
